components.css:
.ds-btn { font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; font-size: 14px; font-weight: 500; min-height: 34px; padding: 5px 12px; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: var(--paper, #ffffff); color: var(--ink, #0b0b0b); cursor: pointer; }
.ds-btn:hover:not(:disabled) { background: var(--concrete, #e6e6e6); }
.ds-btn:focus-visible { outline: 3px solid var(--ink, #0b0b0b); outline-offset: 2px; }
.ds-btn:disabled { cursor: not-allowed; color: #9a9a9a; border-color: #9a9a9a; border-style: dashed; background: #ffffff; }

.ds-btn-primary { font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; font-size: 14px; font-weight: 700; min-height: 34px; padding: 5px 12px; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: var(--yw, #ffcc00); color: var(--ink, #0b0b0b); cursor: pointer; }
.ds-btn-primary:hover:not(:disabled) { background: #f2c200; }
.ds-btn-primary:focus-visible { outline: 3px solid var(--ink, #0b0b0b); outline-offset: 2px; }
.ds-btn-primary:disabled { cursor: not-allowed; color: #9a9a9a; border-color: #9a9a9a; border-style: dashed; background: #ffffff; }

.ds-field { display: grid; gap: 4px; font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; font-size: 11px; font-weight: 500; color: var(--muted, #6b6b6b); }
.ds-input { font: inherit; font-size: 12px; min-height: 30px; padding: 4px 8px; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: var(--paper, #ffffff); color: var(--ink, #0b0b0b); }
.ds-input::placeholder { color: #767676; }
.ds-input:focus-visible { outline: 3px solid var(--ink, #0b0b0b); outline-offset: 2px; }

.ds-navgroup { display: flex; align-items: stretch; gap: 6px; flex-wrap: wrap; }
.ds-nav-item { display: flex; align-items: baseline; gap: 7px; font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; font-size: 12.5px; font-weight: 500; min-height: 34px; padding: 6px 13px; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: var(--paper, #ffffff); color: var(--ink, #0b0b0b); cursor: pointer; white-space: nowrap; }
.ds-nav-item small { font-size: 10.5px; color: var(--muted, #6b6b6b); font-weight: 500; margin-left: 4px; }
.ds-nav-item:hover:not(.ds-nav-item--active) { background: var(--concrete, #e6e6e6); }
.ds-nav-item--active { background: var(--yw, #ffcc00); font-weight: 700; }
.ds-nav-item--active small { color: #5c4a00; }
.ds-nav-item:focus-visible { outline: 3px solid var(--ink, #0b0b0b); outline-offset: 2px; }
.ds-nav-mark { font-weight: 900; font-size: 13px; }

.ds-badge { display: inline-block; width: fit-content; padding: 1px 9px; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: var(--paper, #ffffff); color: var(--ink, #0b0b0b); font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; font-size: 11px; line-height: 1.7; font-weight: 500; white-space: nowrap; }
.ds-badge.ds-good { color: var(--good, #0a7d32); }
.ds-badge.ds-warning { color: var(--warn, #8a6116); }
.ds-badge.ds-error { color: var(--err, #a4343a); }

.ds-facts { display: flex; align-items: stretch; border: 2px solid var(--ink, #0b0b0b); background: #ffffff; font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; }
.ds-facts-cell { flex: 1; min-width: 0; padding: 13px 16px; border-right: 2px solid var(--ink, #0b0b0b); }
.ds-facts-cell:first-child { flex: 1.6; }
.ds-facts-cell:last-child { border-right: 0; }
.ds-facts-cell h3 { font-size: 11.5px; color: var(--muted, #6b6b6b); letter-spacing: .1em; margin: 0 0 8px; font-weight: 500; }
.ds-facts-req { font-size: 14px; line-height: 1.75; margin: 0; color: var(--ink, #0b0b0b); }
.ds-facts-kv { font-weight: 700; font-size: 14px; margin: 0; color: var(--ink, #0b0b0b); }
.ds-facts-big { font-size: 26px; font-weight: 900; margin: 4px 0 0; font-variant-numeric: tabular-nums; color: var(--ink, #0b0b0b); }
.ds-facts-big small { font-size: 12px; font-weight: 500; color: var(--muted, #6b6b6b); margin-left: 6px; }

.ds-panel { border: 2px solid var(--ink, #0b0b0b); background: #ffffff; border-radius: 2px; overflow: hidden; font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; }
.ds-section-head { display: flex; justify-content: space-between; align-items: center; gap: 14px; padding: 10px 16px; background: var(--ink, #0b0b0b); color: #ffffff; border-bottom: 2px solid var(--ink, #0b0b0b); }
.ds-section-head h2 { margin: 0; color: #ffffff; font-size: 13.5px; font-weight: 700; }
.ds-section-head > span { color: #c9c9c9; font-size: 11.5px; }
.ds-section-note { margin: 0; padding: 10px 16px; font-size: 11.5px; color: var(--soft, #4a4a4a); background: var(--plaster, #f7f7f7); border-bottom: 1px solid var(--hair, #d8d8d8); }
.ds-panel-body { padding: 16px; font-size: 13px; line-height: 1.85; color: var(--ink, #0b0b0b); }

.ds-table-scroll { overflow: auto; }
.ds-table { border-collapse: collapse; width: 100%; text-align: left; font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; font-size: 12.5px; color: var(--ink, #0b0b0b); }
.ds-table th { color: var(--soft, #4a4a4a); font-weight: 600; background: var(--plaster, #f7f7f7); padding: 10px 12px; border-bottom: 2px solid var(--ink, #0b0b0b); font-size: 11px; white-space: nowrap; }
.ds-table td { padding: 11px 12px; border-bottom: 1px solid var(--hair, #d8d8d8); vertical-align: top; }
.ds-table tr:last-child td { border-bottom: 0; }
.ds-number, .ds-money { text-align: right; font-variant-numeric: tabular-nums; }
.ds-money { white-space: nowrap; font-weight: 700; font-family: Consolas, "Cascadia Mono", monospace; font-size: 13px; }
.ds-id { font-size: 12.5px; }
.ds-cell-note { display: block; font-size: 11px; color: var(--muted, #6b6b6b); margin-top: 4px; }
.ds-seq { font-size: 16px; font-weight: 900; font-variant-numeric: tabular-nums; }
.ds-status { display: inline-block; padding: 1px 9px; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: #ffffff; color: var(--good, #0a7d32); font-size: 11px; font-weight: 500; line-height: 1.7; white-space: nowrap; }

.ds-subbar { display: flex; align-items: center; gap: 10px 14px; flex-wrap: wrap; padding: 8px 22px; background: var(--concrete, #e6e6e6); border-bottom: 2px solid var(--ink, #0b0b0b); font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; font-size: 12px; color: var(--ink, #0b0b0b); }
.ds-sub-label { font-size: 11.5px; font-weight: 500; color: var(--soft, #4a4a4a); }
.ds-sub-select { font: inherit; font-size: 12px; min-height: 30px; padding: 4px 8px; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: #ffffff; color: var(--ink, #0b0b0b); }
.ds-sub-import { font: inherit; font-size: 12px; font-weight: 500; min-height: 30px; padding: 2px 10px; margin-left: auto; border: 2px solid var(--ink, #0b0b0b); border-radius: 2px; background: #ffffff; color: var(--ink, #0b0b0b); cursor: pointer; }
.ds-sub-import:hover { background: var(--concrete, #e6e6e6); }
.ds-sub-select:focus-visible, .ds-sub-import:focus-visible { outline: 3px solid var(--ink, #0b0b0b); outline-offset: 2px; }

.ds-exitrow { display: flex; justify-content: flex-end; align-items: center; gap: 16px; padding: 6px 22px 12px; background: var(--paper, #ffffff); border-top: 1px solid var(--hair, #d8d8d8); font-family: "Noto Sans SC","Microsoft YaHei UI","PingFang SC",system-ui,sans-serif; }
.ds-exit-cap { color: var(--muted, #6b6b6b); font-size: 11px; }
.ds-exit-plate { display: flex; align-items: stretch; background: var(--ink, #0b0b0b); color: #ffffff; border-radius: 2px; overflow: hidden; box-shadow: 0 10px 30px -18px rgba(0, 0, 0, .5); }
.ds-exit-plate a { text-decoration: none; display: flex; align-items: center; }
.ds-exit-back { gap: 8px; padding: 12px 18px; color: #8f8f8f; font-size: 12px; font-weight: 500; border-right: 1px solid #2c2c2c; }
.ds-exit-back b { color: #c9c9c9; font-weight: 900; }
.ds-exit-back:hover { color: var(--yw, #ffcc00); }
.ds-exit-go { gap: 12px; padding: 12px 20px; font-size: 14px; font-weight: 700; color: #ffffff; }
.ds-exit-go b { color: var(--yw, #ffcc00); font-weight: 900; font-size: 15px; }
.ds-exit-go small { font-weight: 500; font-size: 11.5px; color: #c9c9c9; }
.ds-exit-go:hover { background: #1c1c1c; }
.ds-exit-arrow { display: grid; place-items: center; width: 52px; background: var(--yw, #ffcc00); color: var(--ink, #0b0b0b); font-size: 22px; font-weight: 900; }
.ds-exit-plate a:focus-visible { outline: 3px solid var(--ink, #0b0b0b); outline-offset: 2px; }
